
'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const safeLoad=(k,f)=>{try{const scope=localStorage.getItem('veyra-active-user')||'legacy';const v=JSON.parse(localStorage.getItem('veyra-'+(scope==='legacy'?'legacy-':'user-'+scope+'-')+k));return v??f}catch{return f}};
let veyraCloudReady=false,veyraCloudTimer=null,veyraCloudBusy=false,veyraCloudPending=false;
const veyraCloudKeys=['tasks','notes','activity','settings','events','messages','calendar','focus'];
function veyraLocalWorkspace(){const out={};for(const k of veyraCloudKeys){try{const scope=localStorage.getItem('veyra-active-user')||'legacy';const raw=localStorage.getItem('veyra-'+(scope==='legacy'?'legacy-':'user-'+scope+'-')+k);if(raw!==null)out[k]=JSON.parse(raw)}catch{}}return out}
function veyraSetCloudStatus(s){const el=document.getElementById('cloudSyncStatus');if(el)el.textContent=s}
async function veyraWriteCloud(){if(!veyraCloudReady)return; if(veyraCloudBusy){veyraCloudPending=true;return}veyraCloudBusy=true;try{const {data:{user}}=await veyraAuthClient.auth.getUser();if(!user)throw new Error('Not signed in');const workspace=veyraLocalWorkspace();const bytes=JSON.stringify(workspace);if(bytes.length>450000)throw new Error('Workspace is too large to sync. Export a backup and remove large items.');const {error}=await veyraAuthClient.from('user_workspace').upsert({user_id:user.id,workspace,updated_at:new Date().toISOString()},{onConflict:'user_id'});if(error)throw error;veyraSetCloudStatus('Cloud sync · Saved')}catch(err){veyraSetCloudStatus('Cloud sync · Paused');console.warn('VEYRA cloud sync:',err.message)}finally{veyraCloudBusy=false;if(veyraCloudPending){veyraCloudPending=false;veyraWriteCloud()}}}
function veyraScheduleCloudSave(){if(!veyraCloudReady)return;clearTimeout(veyraCloudTimer);veyraSetCloudStatus('Cloud sync · Saving…');veyraCloudTimer=setTimeout(veyraWriteCloud,1000)}
async function veyraInitializeCloudSync(){try{const {data:{user},error:authError}=await veyraAuthClient.auth.getUser();if(authError)throw authError;if(!user)return;veyraSetCloudStatus('Cloud sync · Connecting…');const {data,error}=await veyraAuthClient.from('user_workspace').select('workspace').eq('user_id',user.id).maybeSingle();if(error)throw error;const local=veyraLocalWorkspace();const cloud=data?.workspace&&typeof data.workspace==='object'&&!Array.isArray(data.workspace)?data.workspace:{};const cloudHasData=Object.keys(cloud).length>0;const merged=cloudHasData?{...local,...cloud}:local;for(const k of veyraCloudKeys){if(Object.prototype.hasOwnProperty.call(merged,k)){const scope=localStorage.getItem('veyra-active-user')||'legacy';localStorage.setItem('veyra-user-'+user.id+'-'+k,JSON.stringify(merged[k]))}}veyraCloudReady=true;if(!cloudHasData||Object.keys(merged).some(k=>!Object.prototype.hasOwnProperty.call(cloud,k)))await veyraWriteCloud();else veyraSetCloudStatus('Cloud sync · Connected');if(cloudHasData){tasks=safeLoad('tasks',defaults);notes=safeLoad('notes','');activity=safeLoad('activity',[]);settings=safeLoad('settings',settings);render()}}catch(err){veyraCloudReady=false;veyraSetCloudStatus('Cloud sync · Offline');console.warn('VEYRA cloud sync setup:',err.message)}}
const save=(k,v)=>{try{const scope=localStorage.getItem('veyra-active-user')||'legacy';localStorage.setItem('veyra-'+(scope==='legacy'?'legacy-':'user-'+scope+'-')+k,JSON.stringify(v));veyraScheduleCloudSave();return true}catch{toast('Browser storage is full. Export your data or remove old items.');return false}};
const defaults=[{id:1,title:'Finish Astra Chat setup',detail:'Today · 4:00 PM',tag:'HIGH',done:false},{id:2,title:'Math homework',detail:'Today · 6:00 PM',tag:'MEDIUM',done:false},{id:3,title:'Read The Fate of Elysian',detail:'Today · 8:00 PM',tag:'MEDIUM',done:false}];
let tasks=safeLoad('tasks',defaults),notes=safeLoad('notes',''),activity=safeLoad('activity',[{title:'VEYRA workspace ready',detail:'Your local dashboard is initialized'}]),settings=safeLoad('settings',{light:false,compact:false,profileName:'Personal',profilePicture:'',startupPage:'home',reducedMotion:false});
let current='home',toastTimer;let focusState=safeLoad('focus',{duration:1500,remaining:1500,running:false,endAt:null,sessions:0});if(!focusState||typeof focusState!=='object')focusState={duration:1500,remaining:1500,running:false,endAt:null,sessions:0};
const names={home:'Home',apps:'Apps',tasks:'Tasks',notes:'Notes',files:'Files',calendar:'Calendar',messages:'Messages',voice:'Voice & Video',community:'Community',gaming:'Gaming',ai:'AI Assistant',weather:'Weather',activity:'Activity',focus:'Focus Timer',settings:'Settings'};
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function safeImageData(value){if(typeof value!=='string'||value.length>380000)return '';return /^data:image\/(?:png|jpeg|webp);base64,[A-Za-z0-9+/]+=*$/.test(value)?value:''}
function safeAccent(value){return typeof value==='string'&&/^#[0-9a-fA-F]{6}$/.test(value)?value:'#268cff'}
function safeOverlay(value){const n=Number(value);return Number.isFinite(n)?String(Math.min(.9,Math.max(.45,n))):'.72'}
function log(title){activity.unshift({title,detail:new Date().toLocaleString()});activity=activity.slice(0,30);save('activity',activity)}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2500)}
function dateTick(){const d=new Date();$('#clock').textContent=d.toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});$('#date').textContent=d.toLocaleDateString([],{month:'short',day:'numeric',year:'numeric'})}
function head(k,title,desc,btn=''){return '<div class="page-head"><div class="eyebrow">'+k+'</div><h1 style="font-size:clamp(27px,3vw,38px);letter-spacing:-.04em;margin:0 0 7px">'+title+'</h1><p style="font-size:12px;color:var(--muted);margin:0 0 18px;line-height:1.6">'+desc+'</p>'+btn+'</div>'}
function taskRow(t){const overdue=t.dueDate&&!t.done&&new Date(t.dueDate+'T23:59:59')<new Date();return '<div class="task '+(t.done?'done':'')+'"><input type="checkbox" data-task="'+esc(t.id)+'" '+(t.done?'checked':'')+' aria-label="Complete '+esc(t.title)+'"><div class="task-copy"><b>'+esc(t.title)+'</b><small>'+esc(t.detail||t.category||'Personal task')+(t.category?' · '+esc(t.category):'')+(t.dueDate?' · Due '+esc(new Date(t.dueDate+'T12:00:00').toLocaleDateString()):'')+'</small></div><span class="tag '+(overdue||t.priority==='High'?'high':t.priority==='Low'?'low':'')+'">'+(t.done?'DONE':overdue?'OVERDUE':esc(t.priority||t.tag||'NORMAL').toUpperCase())+'</span><div class="task-actions"><button type="button" class="task-mini" data-task-edit="'+esc(t.id)+'" aria-label="Edit '+esc(t.title)+'" title="Edit task">✎</button><button type="button" class="task-mini danger" data-task-delete="'+esc(t.id)+'" aria-label="Delete '+esc(t.title)+'" title="Delete task">×</button></div></div>'}
